public object FfiConverterTypeVeilIdentity: FfiConverter<VeilIdentity, Pointer> {

    override fun lower(value: VeilIdentity): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): VeilIdentity {
        return VeilIdentity(value)
    }

    override fun read(buf: ByteBuffer): VeilIdentity {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: VeilIdentity) = 8UL

    override fun write(value: VeilIdentity, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}


