sealed class VeilException: kotlin.Exception() {

    class Crypto(

        val `msg`: kotlin.String
        ) : VeilException() {
        override val message
            get() = "msg=${ `msg` }"
    }

    class InvalidInput(

        val `msg`: kotlin.String
        ) : VeilException() {
        override val message
            get() = "msg=${ `msg` }"
    }

    class Session(

        val `msg`: kotlin.String
        ) : VeilException() {
        override val message
            get() = "msg=${ `msg` }"
    }


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<VeilException> {
        override fun lift(error_buf: RustBuffer.ByValue): VeilException = FfiConverterTypeVeilError.lift(error_buf)
    }


}

/**
 * @suppress
 */
public object FfiConverterTypeVeilError : FfiConverterRustBuffer<VeilException> {
    override fun read(buf: ByteBuffer): VeilException {


        return when(buf.getInt()) {
            1 -> VeilException.Crypto(
                FfiConverterString.read(buf),
                )
            2 -> VeilException.InvalidInput(
                FfiConverterString.read(buf),
                )
            3 -> VeilException.Session(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: VeilException): ULong {
        return when(value) {
            is VeilException.Crypto -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is VeilException.InvalidInput -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is VeilException.Session -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
        }
    }

    override fun write(value: VeilException, buf: ByteBuffer) {
        when(value) {
            is VeilException.Crypto -> {
                buf.putInt(1)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is VeilException.InvalidInput -> {
                buf.putInt(2)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is VeilException.Session -> {
                buf.putInt(3)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




